// ─── File: SoeVsOomDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.soe;

import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SoeVsOomDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        InterestCalculator calc = new InterestCalculator();

        // CORRECT iterative version → no stack growth, no overflow.
        BigDecimal correct = calc.compoundIterative(rajesh.getBalance(),
                new BigDecimal("0.05"), 12);
        log.info(() -> "Iterative compound (12 periods): Rs." + correct);

        // BUGGY recursion with NO base case → StackOverflowError (per-thread stack).
        try {
            calc.compoundBuggy(rajesh.getBalance(), new BigDecimal("0.05"), 1);
        } catch (StackOverflowError e) {
            // We catch here ONLY to demonstrate the symptom in the demo.
            log.severe(() -> "StackOverflowError: runaway recursion exhausted the "
                    + "THREAD stack (fix the base case, not the heap)");
        }

        // Illustrate the thread-creation OOM fix: use a BOUNDED pool, never
        // spawn unbounded threads (which would cause 'unable to create new native thread').
        TaskRunner runner = new TaskRunner(4); // fixed pool of 4
        runner.runSample("interest-batch");
        runner.shutdown();

        log.info(() -> "OOM is NOT always heap: it can be Metaspace, native thread, "
                + "direct buffer, or GC-overhead — read the MESSAGE to pick the fix");
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in InterestCalculator.java ───
class InterestCalculator {
    // BUG: no base case → each call pushes a frame forever → StackOverflowError.
    BigDecimal compoundBuggy(BigDecimal principal, BigDecimal rate, int period) {
        BigDecimal grown = principal.multiply(BigDecimal.ONE.add(rate));
        return compoundBuggy(grown, rate, period + 1); // never stops!
    }

    // FIX: iteration with a clear bound → constant stack usage.
    BigDecimal compoundIterative(BigDecimal principal, BigDecimal rate, int periods) {
        BigDecimal amount = principal;
        for (int i = 0; i < periods; i++) {
            amount = amount.multiply(BigDecimal.ONE.add(rate));
        }
        return amount.setScale(2, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Would be in TaskRunner.java (bounded threads avoid thread OOM) ───
class TaskRunner {
    private static final Logger log = Logger.getLogger("BankLog");
    private final ExecutorService pool;

    TaskRunner(int threads) {
        // Bounded pool: never 'unable to create new native thread' from runaway spawning.
        this.pool = Executors.newFixedThreadPool(threads);
    }
    void runSample(String name) {
        pool.submit(() -> log.info(() -> "Ran task " + name + " on bounded pool"));
    }
    void shutdown() { pool.shutdown(); }
}
